Given a matrix mat[][] of size m × n and a positive integer ind (0 ≤ ind < m), determine all row indices i such that the elements of row i form a permutation of the elements in row ind.It is guaranteed that every row contains distinct elements.Note: Two rows are considered permutations of each other if they contain the same elements in any order.Examples:  Input: ind = 3 , mat[][] = [[3, 1, 4, 2],                                            [1, 6, 9, 3],                                          [1, 2, 3, 4],                                         [4, 3, 2, 1]] Output: 0 2Explanation: Rows at indexes 0 and 2 are permutations of row at index 3. Input : ind = 0, mat[][] = [[1, 2],                                             [2, 1]]Output: 1Explanation: Row at indexes 1 is permutation of row at index 0. Table of Content[Naive Approach] - Using Sorting - O(m × n × log n) Time and O(1) Space[Expected Approach] - Using HashSet - O(m ×  n) Time and O(n) Space[Naive Approach] - Using Sorting - O(m × n × log n) Time and O(1) SpaceThe idea is to sort all the rows of matrix mat[][] and check all the rows. If any row is completely equal to the row at index ind, it means the row is a permutation of the given row. 
            C++

    #include<iostream>
#include<vector>
using namespace std;

vector<int> permutedRows(vector<vector<int>>& mat, int ind) {


    vector<int>result;

    // sort all the rows
    for(int i = 0; i<mat.size(); i++){
        sort(mat[i].begin(), mat[i].end());
    }

    for(int i = 0; i<mat.size(); i++){

        // skip if the i is equal to ind
        if(i == ind)
            continue;

        // check if the row is permuted or not
        if(mat[i] == mat[ind]){
            result.push_back(i);
        }
    }
    return result;
}

int main() {
    vector<vector<int>> mat = {{3, 1, 4, 2}, 
                   {1, 6, 9, 3},
                   {1, 2, 3, 4},
                   {4, 3, 2, 1}};
    int ind = 3;

    vector<int>result=permutedRows(mat, ind);
    for(auto&i:result){
        cout<<i<<" ";

    }
    return 0;
}


