        mat.add(new ArrayList<>(Arrays.asList(1, 2, 3, 4)));
        mat.add(new ArrayList<>(Arrays.asList(4, 3, 2, 1)));

        int ind = 3;

        List<Integer> result = permutedRows(mat, ind);
        for (int i : result)
            System.out.print(i + " ");
    }
}


